export function getPuzzle(gameId, localDayIndex, slotOfDay) {
  if (!ids.includes(gameId) || !Number.isInteger(localDayIndex) || localDayIndex < 0 || localDayIndex > 13 || !Number.isInteger(slotOfDay) || slotOfDay < 0 || slotOfDay > 2)
    return null;
  return catalog[gameId][localDayIndex * 3 + slotOfDay] || null;
}

export function getPuzzleById(game, id) {
  return catalog[game]?.find(p => p.id === id) || null;
}

export function catalogIntegrity() {
  return ids.every(g =>
    catalog[g].length === 42 &&
    new Set(catalog[g].map(p => p.id)).size === 42 &&
    catalog[g].every((p, i) => p.game === g && p.dayIndex === Math.floor(i / 3) && p.slotOfDay === i % 3)
  );
}

export { ids as gameIds };
